// The application page, the Applications list and the monitoring loaded on demand (docs/56), on
// the plain server and the database e2e/console_server.py seeded for this run: the split by route
// (the login fetches neither the monitoring nor the application page; each comes from the same
// origin when opened), the CSP trial over the chunks, the keyboard, a deep link to a tab, and each
// new state photographed and checked by axe in both themes. The passwords were generated by
// playwright.config.ts.

import { expect, test, type Browser, type Page, type TestInfo } from "@playwright/test";
import { picturedAndChecked } from "./a11y";
import { ADMIN, APP_ADMIN, OPERATOR, ORG_READER, Scan, logIn } from "./session";

test.describe.configure({ mode: "serial" });

/** Every content-security-policy violation the page reports, gathered from its start. */
async function watchPolicy(page: Page): Promise<() => Promise<string[]>> {
  await page.addInitScript(() => {
    const seen: string[] = [];
    Object.assign(window, { policyViolations: seen });
    document.addEventListener("securitypolicyviolation", (event) => {
      seen.push(`${event.violatedDirective} ${event.blockedURI}`);
    });
  });
  return () =>
    page.evaluate(() => (window as unknown as { policyViolations: string[] }).policyViolations);
}

/** The JavaScript files the page has fetched, by name. */
function scripts(requests: string[]): string[] {
  return requests
    .filter((url) => url.endsWith(".js"))
    .map((url) => new URL(url).pathname.split("/").pop() ?? "");
}

async function freshPage(browser: Browser, testInfo: TestInfo): Promise<Page> {
  const context = await browser.newContext({
    baseURL: testInfo.project.use.baseURL,
    viewport: { width: 1400, height: 1000 },
  });
  return context.newPage();
}

function tabs(page: Page) {
  return page.getByRole("navigation", { name: "Application sections" });
}

test("split by route: the login loads neither the monitoring nor the application page; each comes when opened, from this origin, blocking nothing", async ({
  page,
}) => {
  const violations = await watchPolicy(page);
  const requests: string[] = [];
  page.on("request", (request) => requests.push(request.url()));
  await page.goto("/dashboard/");
  await expect(page.getByRole("region", { name: "Log in", exact: true })).toBeVisible();
  const atLogin = scripts(requests);
  expect(atLogin.some((name) => name.startsWith("App-"))).toBe(false);
  expect(atLogin.some((name) => name.startsWith("ApplicationPage-"))).toBe(false);

  await logIn(page, ADMIN);
  await expect(page.getByRole("table", { name: "Applications" })).toBeVisible();
  expect(scripts(requests).some((name) => name.startsWith("ApplicationPage-"))).toBe(false);
  await page
    .getByRole("table", { name: "Applications" })
    .getByRole("link", { name: "App one" })
    .click();
  await expect(page.getByRole("heading", { name: "App one", level: 2 })).toBeVisible();
  expect(scripts(requests).some((name) => name.startsWith("ApplicationPage-"))).toBe(true);
  for (const tab of ["Settings", "Alert rules", "Incidents", "API keys", "Overview"]) {
    await tabs(page).getByRole("link", { name: tab, exact: true }).click();
    await expect(tabs(page).getByRole("link", { name: tab, exact: true })).toHaveAttribute(
      "aria-current",
      "page",
    );
  }
  expect(await violations()).toEqual([]);
  const origin = new URL(page.url()).origin;
  expect(requests.filter((url) => !url.startsWith(origin) && !url.startsWith("data:"))).toEqual([]);
});

test("the monitoring loads on demand for the platform admin, blocking nothing", async ({
  page,
}) => {
  const violations = await watchPolicy(page);
  const requests: string[] = [];
  page.on("request", (request) => requests.push(request.url()));
  await page.goto("/dashboard/");
  await logIn(page, OPERATOR);
  expect(scripts(requests).some((name) => name.startsWith("App-"))).toBe(false);
  await page
    .getByRole("navigation", { name: "Sections", exact: true })
    .getByRole("link", { name: "Monitoring" })
    .click();
  const sections = page.getByRole("tablist", { name: "Monitoring sections" });
  await expect(sections).toBeVisible();
  expect(scripts(requests).some((name) => name.startsWith("App-"))).toBe(true);
  for (const tab of ["Latency", "Capacity", "Applications", "Events", "Overview"]) {
    await sections.getByRole("tab", { name: tab, exact: true }).click();
    await expect(page.getByRole("tabpanel", { name: tab })).toBeVisible();
  }
  expect(await violations()).toEqual([]);
  const origin = new URL(page.url()).origin;
  expect(requests.filter((url) => !url.startsWith(origin) && !url.startsWith("data:"))).toEqual([]);
});

test("by keyboard alone: search the list, open an application, move between its tabs", async ({
  page,
}) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ADMIN);
  const search = page.getByRole("searchbox", { name: "Search" });
  await search.focus();
  await page.keyboard.type("app one");
  const table = page.getByRole("table", { name: "Applications" });
  await expect(table.getByRole("rowheader")).toHaveCount(1);
  const link = table.getByRole("link", { name: "App one" });
  for (let presses = 0; presses < 30; presses += 1) {
    if (await link.evaluate((element) => element === document.activeElement)) break;
    await page.keyboard.press("Tab");
  }
  await expect(link).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.getByRole("heading", { name: "App one", level: 2 })).toBeVisible();
  const rules = tabs(page).getByRole("link", { name: "Alert rules", exact: true });
  for (let presses = 0; presses < 30; presses += 1) {
    if (await rules.evaluate((element) => element === document.activeElement)) break;
    await page.keyboard.press("Tab");
  }
  await expect(rules).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(rules).toHaveAttribute("aria-current", "page");
  expect(new URL(page.url()).hash).toBe("#/app/app-one/rules");
  expect(await scan.leaks(page)).toEqual([]);
});

test("a deep link to a tab from logged out opens it after login, the old address too", async ({
  browser,
}, testInfo) => {
  for (const [hash, tab] of [
    ["#/app/app-one/keys", "API keys"],
    ["#/application/app-one", "Settings"],
  ] as const) {
    const page = await freshPage(browser, testInfo);
    await page.goto(`/dashboard/${hash}`);
    await expect(page.getByRole("region", { name: "Log in", exact: true })).toBeVisible();
    await logIn(page, ADMIN);
    await expect(tabs(page).getByRole("link", { name: tab, exact: true })).toHaveAttribute(
      "aria-current",
      "page",
    );
    expect(new URL(page.url()).hash).toBe(hash);
    await page.context().close();
  }
});

test("each new state, photographed and checked by axe in both themes", async ({
  page,
}, testInfo) => {
  const scan = new Scan();
  scan.watch(page);
  await page.goto("/dashboard/");
  await logIn(page, ADMIN);
  await expect(page.getByRole("table", { name: "Applications" })).toBeVisible();
  await page.getByRole("combobox", { name: "Status" }).selectOption("firing");
  await picturedAndChecked(page, testInfo, "ui4-list-filtered");
  await page.getByRole("searchbox", { name: "Search" }).fill("no such application");
  await expect(page.getByText(/No application on this page matches/)).toBeVisible();
  await picturedAndChecked(page, testInfo, "ui4-list-no-match");

  await page.evaluate(() => {
    window.location.hash = "#/app/app-one/overview";
  });
  const figures = page.getByRole("region", { name: "Figures", exact: true });
  await expect(figures).toContainText("last 60 minutes");
  await expect(figures).toContainText("not a series");
  await picturedAndChecked(page, testInfo, "ui4-overview-org-admin");
  expect(await scan.leaks(page)).toEqual([]);
});

test("an organization reader and an application's admin: the Overview says what each may read", async ({
  browser,
}, testInfo) => {
  let page = await freshPage(browser, testInfo);
  await page.goto("/dashboard/#/app/app-one/overview");
  await logIn(page, ORG_READER);
  await expect(page.getByRole("region", { name: "Figures", exact: true })).toContainText(
    "last 60 minutes",
  );
  await picturedAndChecked(page, testInfo, "ui4-overview-org-reader");
  await page.context().close();

  page = await freshPage(browser, testInfo);
  const requests: string[] = [];
  page.on("request", (request) => requests.push(request.url()));
  await page.goto("/dashboard/");
  await logIn(page, APP_ADMIN);
  const figures = page.getByRole("region", { name: "Figures", exact: true });
  await expect(figures).toContainText("not available to this account yet");
  expect(requests.some((url) => url.includes("/metrics"))).toBe(false);
  await picturedAndChecked(page, testInfo, "ui4-overview-app-admin");
  await page.context().close();
});
